// Des: Send messages, friend requests, group joins, page posts
// Flo: plan steps > known contact sends freely, new contact or friend request needs --force approval > safety ladder
// I/O: Args to, text, url (caller) > Out; same message to the same person is never sent twice
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const flow = @import("ru-flow-runz.zig"); const post = @import("ru-post-main.zig");
pub fn dmRun(ctx: *task.Ctx, args: task.Args) !task.Out { if (args.to.len == 0 or args.text.len == 0) return error.BadUsage; const known = try ctx.store.knowHas(args.to); const hsh = try task.hashHex(ctx, args.text); const key = try std.fmt.allocPrint(ctx.aren, "dm|{s}|{s}", .{ args.to, hsh }); const what = try std.fmt.allocPrint(ctx.aren, "message {s} ({s} contact): {s}", .{ args.to, if (known) "known" else "NEW", post.cutUtf8(args.text, 40) }); const path = try std.fmt.allocPrint(ctx.aren, "{s}{s}", .{ ctx.conf.path_dmsg_thre, args.to }); const stps = try ctx.aren.dupe(flow.Step, &.{ task.goStep(path), .{ .op = .typez, .labs = ctx.conf.labl_dmsg_boxz, .text = args.text }, .{ .op = .key, .text = "Enter", .commit = true } }); const out = try task.execWrite(ctx, .dmsg, key, what, !known, stps); if (out == .done) try ctx.store.knowAdd(args.to, task.nowMs(ctx)); return out; }
pub fn friendRun(ctx: *task.Ctx, args: task.Args) !task.Out { if (args.url.len == 0) return error.BadUsage; const key = try std.fmt.allocPrint(ctx.aren, "frie|{s}", .{args.url}); const what = try std.fmt.allocPrint(ctx.aren, "send a friend request at {s}", .{args.url}); const stps = try ctx.aren.dupe(flow.Step, &.{ task.goStep(args.url), .{ .op = .click, .labs = ctx.conf.labl_frie_addz, .commit = true } }); return task.execWrite(ctx, .frie, key, what, true, stps); }
pub fn joinRun(ctx: *task.Ctx, args: task.Args) !task.Out { if (args.url.len == 0) return error.BadUsage; const key = try std.fmt.allocPrint(ctx.aren, "join|{s}", .{args.url}); const what = try std.fmt.allocPrint(ctx.aren, "join the group at {s}", .{args.url}); const stps = try ctx.aren.dupe(flow.Step, &.{ task.goStep(args.url), .{ .op = .click, .labs = ctx.conf.labl_grou_join, .commit = true } }); return task.execWrite(ctx, .grou, key, what, false, stps); }
pub fn pageRun(ctx: *task.Ctx, args: task.Args) !task.Out { if (args.url.len == 0 or args.text.len == 0) return error.BadUsage; return post.postTo(ctx, args.text, args.url, .post); }
